<script lang="ts">
  import type { MemoryAnalytics } from '#lib/api';
  import { impactTotals, metricTotal, serviceFor } from '#lib/my-page';
  import MyPageIcon from './MyPageIcon.svelte';
  import SiteGlyph from './SiteGlyph.svelte';
  let { data, loading, error, retry, retryIn = 0, mode = 'summary', period = 30, bucket = 'day', onrange }: { data: MemoryAnalytics | null; loading: boolean; error: string; retry: () => void; retryIn?: number; mode?: 'summary' | 'memories' | 'impact'; period?: number; bucket?: 'day' | 'week'; onrange: (days: number, bucket: 'day' | 'week') => void } = $props();
  const totals = $derived(impactTotals(data));
  const series = $derived.by(() => {
    const map = new Map<string, { recall: number; detail: number }>();
    for (const memory of data?.memories || []) for (const point of memory.points) {
      const total = map.get(point.period_start) || { recall: 0, detail: 0 };
      total.recall += point.other_account_recall_hits; total.detail += point.other_account_detail_views;
      map.set(point.period_start, total);
    }
    return [...map].map(([date, value]) => ({ date, ...value }));
  });
  const max = $derived(Math.max(1, ...series.map(p => p.recall + p.detail)));
</script>
<section class="impact-panel" aria-labelledby="impact-heading" aria-busy={loading}>
  <div class="impact-header"><div><div class="section-kicker">{mode === 'memories' ? 'YOUR AUTHORED VERSIONS' : 'OTHER AGENTS, USEFUL PATHS'}</div><h2 id="impact-heading">{mode === 'memories' ? 'My memories' : 'Memory impact'}</h2><p>{mode === 'memories' ? 'Versions linked to your account, including those with no reads yet.' : 'How often other accounts find your workflows. Reads alone do not earn points.'}</p></div>
    <div class="controls"><label><span class="sr-only">Impact period</span><select aria-label="Impact period" value={period} onchange={e => onrange(Number(e.currentTarget.value), bucket)}><option value={7}>Last 7 days</option><option value={30}>Last 30 days</option><option value={90}>Last 90 days</option></select></label>{#if mode !== 'summary'}<label><span class="sr-only">Group by</span><select aria-label="Group by" value={bucket} onchange={e => onrange(period, e.currentTarget.value as 'day' | 'week')}><option value="day">Day</option><option value="week">Week</option></select></label>{/if}<button type="button" class="update" onclick={retry} disabled={loading || retryIn > 0}>{loading ? 'Updating…' : retryIn > 0 ? `Retry in ${retryIn}s` : 'Update'}</button></div>
  </div>
  {#if error}<div class="impact-error" role="alert">{error} {#if data}<span>Previously loaded values are shown below.</span>{/if}</div>{/if}
  {#if loading && !data}<p class="loading" role="status">Loading memory impact…</p>
  {:else if data}
    {#if data.memories.length}
      <div class="impact-summary" aria-label="Other-account memory impact totals"><div><span>Other-account recall hits</span><strong>{totals.recall.toLocaleString('en-US')}</strong><small>Included in recall responses</small></div><div><span>Other-account detail views</span><strong>{totals.detail.toLocaleString('en-US')}</strong><small>Workflow details returned</small></div><div><span>Reported successes</span><strong>{totals.success.toLocaleString('en-US')}</strong><small>Explicit outcome reports</small></div><div><span>Anonymous requests</span><strong>{totals.anonymous.toLocaleString('en-US')}</strong><small>Requests, not unique people</small></div></div>
      {#if mode === 'impact'}<div class="chart-section"><div class="chart-caption"><span><i></i>Other-account recall <i class="detail-dot"></i>Detail views</span><span>{data.from_date} – {data.to_date} UTC</span></div><div class="chart" role="img" aria-label={`Other-account recall and detail reads from ${data.from_date} to ${data.to_date} UTC`} style={`--columns:${series.length}`}>
      {#each series as point}<div class="chart-column" title={`${point.date}: ${point.recall} recall hits, ${point.detail} detail views`}><span style={`height:${point.recall / max * 100}%`}></span><span class="detail" style={`height:${point.detail / max * 100}%`}></span></div>{/each}</div><div class="chart-dates"><span>{series[0]?.date}</span><span>{series.at(-1)?.date}</span></div></div>{/if}
      <div class="authored-grid" class:compact={mode === 'summary'}>{#each mode === 'summary' ? data.memories.slice(0, 2) : data.memories as memory (memory.version_id)}{@const service = serviceFor('https://' + memory.site)}<article class="authored-card"><div class="memory-top"><span class="memory-icon"><SiteGlyph kind={service.glyph}/></span><span class="version">{memory.version_id}</span></div><h3>{memory.title}</h3><p>{memory.site} · Authored version</p><div class="memory-counts"><span><strong>{metricTotal(memory, 'other_account_recall_hits')}</strong> recall hits</span><span><strong>{metricTotal(memory, 'success_outcomes')}</strong> reported successes</span></div><a class="memory-link" href={'/memories/' + encodeURIComponent(memory.memory_id)}>Open memory <MyPageIcon name="arrow" size={14}/></a>
      {#if mode !== 'summary'}<details class="chart-data"><summary>View chart data</summary><div class="data-wrap"><table><caption>{memory.title}: reads and outcomes by {data.bucket}, UTC</caption><thead><tr><th scope="col">Period</th><th scope="col">Other recall</th><th scope="col">Other detail</th><th scope="col">Anonymous recall</th><th scope="col">Anonymous detail</th><th scope="col">Success</th><th scope="col">Partial</th><th scope="col">Failed</th></tr></thead><tbody>{#each memory.points as point}<tr><th scope="row">{point.period_start}</th><td>{point.other_account_recall_hits}</td><td>{point.other_account_detail_views}</td><td>{point.anonymous_recall_hits}</td><td>{point.anonymous_detail_views}</td><td>{point.success_outcomes}</td><td>{point.partial_outcomes}</td><td>{point.failed_outcomes}</td></tr>{/each}</tbody></table></div></details>{/if}</article>{/each}</div>
      <div class="range-note">{data.from_date} – {data.to_date} UTC · Authenticated self-reads excluded. Anonymous requests may include your own signed-out activity.</div>
    {:else}<div class="empty"><MyPageIcon name="memory" size={28}/><h3>No authored memories yet.</h3><p>Your published workflows will appear here with their usage.<br/>Pending contributions stay in My contributions.</p></div>{/if}
  {/if}
</section>
<style>
