rder-collapse:collapse;text-align:right;font-size:9px;white-space:nowrap}caption{text-align:left;white-space:normal;padding-bottom:8px}td,th{padding:6px;border-bottom:1px solid #e7ecde}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:900px){.impact-header{flex-direction:column}.controls{flex-wrap:wrap}.authored-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.impact-summary>div{padding:14px 11px}.impact-summary span{font-size:9px}}
@media(max-width:600px){.impact-panel{padding:19px 17px}.impact-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.impact-summary>div:nth-child(2){border-right:0}.impact-summary>div:nth-child(-n+2){border-bottom:1px solid #e6ebdf}.authored-grid,.authored-grid.compact{grid-template-columns:1fr}.impact-summary strong{font-size:25px}.chart{gap:3px;height:100px}.chart-caption{flex-direction:column}.range-note{font-size:10px}}
</style>
